# sp8lib.py -- cert-07: Sp(8,2) on F_2^8 (labels (x|z), low 4 bits x, high 4 bits z), the signed and unsigned
# permutation modules on quadratic forms, tensor constructions, P_0-pieces via A-characters, cut profiles.
# Conventions copied from meta/c2-finite-group/fg4.py (base frame L0 = span Z(i); depth elements HS[j] =
# t_(e1|e1) ... t_(e(j+1)|e(j+1)); P_0 = A : GL(4,2) with A generated by transvections t_w, w in L0).
import numpy as np
m = 4; NV = 256; MM = 15
PC = np.array([bin(i).count('1') for i in range(NV)])
U = np.arange(NV)
BM = (PC[(U[:, None] & MM) & (U[None, :] >> m)] + PC[(U[None, :] & MM) & (U[:, None] >> m)]) & 1
def trans(w): return np.where(BM[:, w] == 1, U ^ w, U).astype(np.int64)
def comp(g, h): return g[h]                       # apply h first, then g
def inv(g):
    r = np.empty_like(g); r[g] = U; return r
X = lambda i: 1 << (i - 1); Z = lambda i: 1 << (m + i - 1); EE = lambda i: X(i) | Z(i)
gens_w = [X(i) for i in range(1, 5)] + [Z(i) for i in range(1, 5)] + [X(i) | X(i + 1) for i in range(1, 4)] + \
         [Z(i) | Z(i + 1) for i in range(1, 4)] + [EE(1)]
GENS = [trans(w) for w in gens_w]
L0 = sorted({sum(((b >> (i - 1)) & 1) * Z(i) for i in range(1, 5)) for b in range(16)})
L0nz = [w for w in L0 if w]
A_TW = [trans(w) for w in L0nz]                   # the 15 transvections of A (they generate A = Sym(4,2))
def levi(Am):
    Am = np.array(Am) % 2
    M = np.concatenate([Am, np.eye(m, dtype=int)], axis=1)
    for c in range(m):
        p = next(r for r in range(c, m) if M[r, c]); M[[c, p]] = M[[p, c]]
        for r in range(m):
            if r != c and M[r, c]: M[r] ^= M[c]
    AiT = M[:, m:].T
    def ap(Mt, x): return sum(((int(Mt[i] @ np.array([(x >> j) & 1 for j in range(m)])) & 1) << i) for i in range(m))
    return np.array([ap(Am, v & MM) | (ap(AiT, v >> m) << m) for v in range(NV)], dtype=np.int64)
E12 = np.eye(4, dtype=int); E12[0, 1] = 1
CYC = np.roll(np.eye(4, dtype=int), 1, axis=0)
L_GENS = [levi(E12), levi(CYC)]
HS = [trans(EE(1))]
for j in range(2, 5): HS.append(comp(HS[-1], trans(EE(j))))
def frame_dist(g):
    img = {int(g[x]) for x in L0}
    k = len(img & set(L0)); return 4 - int(np.log2(k))
assert [frame_dist(h) for h in HS] == [1, 2, 3, 4]
for L in L_GENS: assert {int(L[x]) for x in L0} == set(L0)

def f2rank(rows):
    rows = [int(r) for r in rows]; rk = 0
    for bit in range(8):
        piv = next((i for i, r in enumerate(rows) if (r >> bit) & 1), None)
        if piv is None: continue
        p = rows.pop(piv); rows = [r ^ p if (r >> bit) & 1 else r for r in rows]; rk += 1
    return rk
def dickson(h):
    # rank over F_2 of (h - 1) mod 2; columns of h - 1 are h(e_i) ^ e_i
    return f2rank([int(h[1 << i]) ^ (1 << i) for i in range(8)]) & 1

Q0 = PC[(U & MM) & (U >> m)] & 1
def qtable(a): return (Q0 ^ BM[a]).astype(np.uint8)
TABLES = {qtable(a).tobytes(): a for a in range(NV)}

class FormModule:
    """(Signed) permutation module on the quadratic forms Q_a = Q0 + B(a, .) of one type (minus: Q0(a) = 1).
    signed=True: Ind from O(Q) of the Dickson sign (GAP: minus -> 35 + 85, plus -> 51 + 85)."""
    def __init__(self, minus=True, signed=True):
        self.signed = signed
        a0 = EE(1) if minus else 0
        self.forms = [a0]; self.idx = {a0: 0}; self.r = {a0: U.copy()}
        k = 0
        while k < len(self.forms):
            a = self.forms[k]; k += 1
            for g in GENS:
                b = self.act(g, a)
                if b not in self.idx:
                    self.idx[b] = len(self.forms); self.forms.append(b); self.r[b] = comp(g, self.r[a])
        self.d = len(self.forms); self.a0 = a0
        self.rinv = {a: inv(r) for a, r in self.r.items()}
        assert self.d == (120 if minus else 136)
    def act(self, g, a):
        return TABLES[qtable(a)[inv(g)].tobytes()]
    def mat(self, g):
        R = np.zeros((self.d, self.d)); gi = inv(g); t0 = qtable(self.a0)
        for a in self.forms:
            b = TABLES[qtable(a)[gi].tobytes()]
            s = 1.0
            if self.signed:
                h = comp(self.rinv[b], comp(g, self.r[a]))
                assert np.array_equal(t0[inv(h)], t0)
                s = -1.0 if dickson(h) else 1.0
            R[self.idx[b], self.idx[a]] = s
        return R

def tsum(matf, d):
    T = np.zeros((d, d))
    for w in range(1, NV): T += matf(trans(w))
    return T

def eig_clusters(T, tol=1e-6):
    w, V = np.linalg.eigh((T + T.T) / 2)
    cl = []; st = 0
    for i in range(1, len(w) + 1):
        if i == len(w) or w[i] - w[i - 1] > tol * max(1.0, abs(w).max()): cl.append((round(float(w[st:i].mean()), 6), V[:, st:i])); st = i
    return cl

class Sub:
    """subrepresentation spanned by orthonormal columns Q of a parent with mat()"""
    def __init__(self, parent, Q):
        self.parent = parent; self.Q = Q; self.d = Q.shape[1]
    def mat(self, g): return self.Q.T @ self.parent.mat(g) @ self.Q

class Lam2:
    def __init__(self, base):
        self.base = base; n = base.d
        self.I, self.J = np.triu_indices(n, 1); self.d = len(self.I)
    def mat(self, g):
        A = self.base.mat(g); I, J = self.I, self.J
        return A[I][:, I] * A[J][:, J] - A[J][:, I] * A[I][:, J]

class Sym2:
    def __init__(self, base):
        self.base = base; n = base.d
        self.I, self.J = np.triu_indices(n, 0); self.d = len(self.I)
        self.c = np.where(self.I == self.J, 1.0, np.sqrt(2.0))   # orthonormal basis e_i e_j scaled
    def mat(self, g):
        A = self.base.mat(g); I, J = self.I, self.J
        M = A[I][:, I] * A[J][:, J] + A[J][:, I] * A[I][:, J]
        # basis b_ij = (e_i e_j + e_j e_i)/c_ij ; image of b_ij = sum_kl M[kl, ij]/(c_ij) * (e_k e_l + e_l e_k)/... normalise:
        cI = self.c
        M = M * (cI[:, None] / cI[None, :])
        M[:, I == J] /= 2.0
        return M

class Tensor:
    def __init__(self, a, b): self.a, self.b = a, b; self.d = a.d * b.d
    def mat(self, g): return np.kron(self.a.mat(g), self.b.mat(g))

def apply_tensor_sub(a_mat, b_mat, Q, da, db):
    """(A (x) B) Q for Q with rows indexed (i, j) -> i*db + j"""
    k = Q.shape[1]
    Y = Q.reshape(da, db, k)
    Z = np.einsum('ai,ijk->ajk', a_mat, Y)
    Z = np.einsum('ajk,bj->abk', Z, b_mat)
    return Z.reshape(da * db, k)

class TensorSub:
    """subrepresentation of a (x) b spanned by orthonormal Q, without forming kron"""
    def __init__(self, a, b, Q): self.a, self.b, self.Q = a, b, Q; self.d = Q.shape[1]
    def mat(self, g):
        return self.Q.T @ apply_tensor_sub(self.a.mat(g), self.b.mat(g), self.Q, self.a.d, self.b.d)

# ---------- P_0 pieces via A-characters, grouped by GL(4,2)-orbits ----------
L0idx = {w: i for i, w in enumerate(L0nz)}
LPERM = [np.array([L0idx[int(L[w])] for w in L0nz]) for L in L_GENS]   # Levi on L0\0
def orbit_of(f):
    f = tuple(f); seen = {f}; st = [f]
    while st:
        x = st.pop()
        for P in LPERM:
            # chi'(t_w) = chi(t_{L^-1 w}):  f'[P[i]] = f[i]
            y = [0] * 15
            for i in range(15): y[P[i]] = x[i]
            y = tuple(y)
            if y not in seen: seen.add(y); st.append(y)
    return frozenset(seen)

def p0_pieces(rep, seed=1, verbose=True):
    d = rep.d
    TW = [rep.mat(t) for t in A_TW]
    rng = np.random.default_rng(seed)
    R = sum(rng.standard_normal() * T for T in TW)
    cl = eig_clusters(R, tol=1e-7)
    groups = {}
    for lam, V in cl:
        f = tuple(int(round(np.trace(V.T @ T @ V) / V.shape[1])) for T in TW)
        assert all(abs(x) == 1 for x in f), f
        ff = tuple(0 if x == 1 else 1 for x in f)
        o = orbit_of(ff)
        groups.setdefault(o, []).append(V)
    pcs = []
    for o, Vs in groups.items():
        Q = np.concatenate(Vs, axis=1)
        rep_f = min(o); nz = sum(rep_f)
        pcs.append(dict(Q=Q, dim=Q.shape[1], orbit=len(o), nchars=len(Vs), weight=nz, rep=rep_f))
    pcs.sort(key=lambda p: (p['dim'], p['orbit']))
    if verbose:
        print("  A-orbit pieces:", [(p['dim'], p['orbit'], p['nchars']) for p in pcs], flush=True)
    return pcs

def profile(rep, QS, QC, tol=1e-7):
    out = []
    for g in HS:
        M = QC.T @ (rep.apply(g, QS) if hasattr(rep, 'apply') else rep.mat(g) @ QS)
        s = np.linalg.svd(M, compute_uv=False) if M.size else np.zeros(0)
        psi = int((s > tol).sum()); phi = float((s ** 2).sum())
        gap = (float(s[s > tol].min()) if psi else None, float(s[s <= tol].max()) if (s <= tol).any() else None)
        out.append(dict(psi=psi, phi=phi, gap=gap))
    return out

# ---------- refinement of A-orbit groups into P_0-irreducibles (multiplicity-free restrictions) ----------
def levi_elements():
    """all 20160 Levi elements as 256-permutations (BFS over L_GENS)"""
    seen = {U.tobytes(): U.copy()}; fr = [U.copy()]
    while fr:
        nx = []
        for g in fr:
            for L in L_GENS:
                h = comp(L, g); k = h.tobytes()
                if k not in seen: seen[k] = h; nx.append(h)
        fr = nx
    els = list(seen.values()); assert len(els) == 20160
    return els
_LEV = None
def LEV():
    global _LEV
    if _LEV is None:
        _LEV = levi_elements()
    return _LEV
def act_pattern(L, f):
    # chi'(t_w) = chi(t_{L^-1 w}) : f'[idx(L w)] = f[idx(w)]
    y = [0] * 15
    for i, w in enumerate(L0nz): y[L0idx[int(L[w])]] = f[i]
    return tuple(y)

def rep_apply(rep, g, V):
    if hasattr(rep, 'apply'): return rep.apply(g, V)
    return rep.mat(g) @ V

def p0_pieces_refined(rep, seed=1, nsamp=40, verbose=True):
    d = rep.d
    TW = [rep.mat(t) if not hasattr(rep, 'apply') else rep.apply(t, np.eye(d)) for t in A_TW]
    rng = np.random.default_rng(seed)
    R = sum(rng.standard_normal() * T for T in TW)
    cl = eig_clusters(R, tol=1e-7)
    groups = {}
    for lam, V in cl:
        f = tuple(int(round(np.trace(V.T @ T @ V) / V.shape[1])) for T in TW)
        assert all(abs(x) == 1 for x in f), f
        ff = tuple(0 if x == 1 else 1 for x in f)
        groups.setdefault(orbit_of(ff), {})[ff] = V
    pcs = []
    for o, fV in groups.items():
        fs = sorted(fV); f0 = fs[0]; V0 = fV[f0]; e = V0.shape[1]
        if e == 1:
            Q = np.concatenate([fV[f] for f in fs], axis=1)
            pcs.append(dict(Q=Q, dim=Q.shape[1], orbit=len(o), e=1)); continue
        # stabiliser samples and coset representatives
        stab = []; reps_ = {}
        for L in LEV():
            f1 = act_pattern(L, f0)
            if f1 == f0: stab.append(L)
            if f1 not in reps_: reps_[f1] = L
        idx = rng.choice(len(stab), size=min(nsamp, len(stab)), replace=False)
        Ms = [V0.T @ rep_apply(rep, stab[i], V0) for i in idx]
        oe = max(np.abs(M @ M.T - np.eye(e)).max() for M in Ms)
        # commutant: X M - M X = 0
        AtA = np.zeros((e * e, e * e))                  # Gram of the commutation system (memory-light; was a full SVD)
        for M in Ms:
            K = np.kron(np.eye(e), M) - np.kron(M.T, np.eye(e)); AtA += K.T @ K
        wq, Vq = np.linalg.eigh(AtA)
        null = Vq[:, wq < 1e-8 * max(1.0, wq.max())].T
        Xs = null.T @ rng.standard_normal(null.shape[0])
        X = Xs.reshape(e, e, order='F'); X = X + X.T
        sub = eig_clusters(X, tol=1e-6)
        for lam, W in sub:
            vecs = []
            for f in fs:
                L = reps_[f]
                Y = rep_apply(rep, L, V0 @ W)
                # must lie in E_f
                res = np.abs(Y - fV[f] @ (fV[f].T @ Y)).max(); assert res < 1e-6, res
                vecs.append(Y)
            Q, _ = np.linalg.qr(np.concatenate(vecs, axis=1))
            pcs.append(dict(Q=Q, dim=Q.shape[1], orbit=len(o), e=e, comm=null.shape[0], stab_orth=float(oe)))
    pcs.sort(key=lambda p: (p['dim'], p['orbit']))
    allQ = np.concatenate([p['Q'] for p in pcs], axis=1)
    oerr = np.abs(allQ.T @ allQ - np.eye(allQ.shape[1])).max()
    assert allQ.shape[1] == d and oerr < 1e-6, (allQ.shape, oerr)
    if verbose:
        print("  P0 pieces (dim, A-orbit, e=dim E_chi0):", [(p['dim'], p['orbit'], p['e']) for p in pcs], f"orth {oerr:.1e}", flush=True)
    return pcs

# ---------- permutation modules on orbits of subsets (frames; S10-structures) ----------
_RW = np.random.default_rng(12345).integers(1, 2**62, size=NV, dtype=np.int64).astype(np.uint64)
def set_keys(sets):          # sets: (n, k) int array of vectors -> uint64 keys (order-free)
    return _RW[sets].sum(axis=1, dtype=np.uint64)
class SetPermModule:
    """permutation module on the Sp(8,2)-orbit of a k-subset S0 of F_2^8 (as rows of vectors)"""
    def __init__(self, S0, expect=None):
        sets = [np.array(sorted(S0), dtype=np.int64)]; keys = {int(set_keys(sets[0][None])[0]): 0}
        fr = np.array(sets)
        while len(fr):
            nx = []
            for g in GENS:
                im = g[fr]; kk = set_keys(im)
                for r in range(len(im)):
                    k = int(kk[r])
                    if k not in keys: keys[k] = len(sets); s = np.sort(im[r]); sets.append(s); nx.append(s)
            fr = np.array(nx) if nx else np.zeros((0, len(S0)), dtype=np.int64)
        self.sets = np.array(sets); self.d = len(sets)
        ks = set_keys(self.sets); self.order = np.argsort(ks); self.sk = ks[self.order]
        if expect: assert self.d == expect, self.d
        self._pc = {}
    def perm(self, g):
        """p with P(g) e_S = e_{gS}:  p[i] = index of g S_i"""
        kb = g.tobytes()
        if kb in self._pc: return self._pc[kb]
        kk = set_keys(g[self.sets]); pos = np.searchsorted(self.sk, kk)
        assert np.all(self.sk[pos] == kk)
        p = self.order[pos]
        if len(self._pc) < 400: self._pc[kb] = p
        return p
    def apply(self, g, V):
        p = self.perm(g); out = np.empty_like(V); out[p] = V; return out

class SubA:
    """subrepresentation (orthonormal columns Q) of a parent with apply()"""
    def __init__(self, parent, Q): self.parent = parent; self.Q = Q; self.d = Q.shape[1]
    def apply(self, g, V): return self.Q.T @ self.parent.apply(g, self.Q @ V)
    def mat(self, g): return self.apply(g, np.eye(self.d))

def tsum_apply(mod, Y):
    out = np.zeros_like(Y)
    for w in range(1, NV): out += mod.apply(trans(w), Y)
    return out

def s10_structure():
    """the 45 transposition vectors e_i + e_j of S10 acting on (even-weight F_2^10)/<1>, mapped into (F_2^8, B)"""
    full = (1 << 10) - 1
    def canon(x): return x ^ full if (x >> 9) & 1 else x
    def bf(x, y): return bin(x & y).count('1') & 1
    E = sorted({canon(x) for x in range(1 << 10) if bin(x).count('1') % 2 == 0})
    assert len(E) == 256
    # symplectic Gram-Schmidt on generators e_i + e_(i+1)
    pool = [canon((1 << i) | (1 << (i + 1))) for i in range(9)]
    def span_add(basis, x): pass
    P, Qv = [], []
    rest = pool[:]
    def proj(x):
        for p, q in zip(P, Qv):
            if bf(x, q): x ^= p
            if bf(x, p): x ^= q
        return canon(x)
    while len(P) < 4:
        rest = [proj(x) for x in rest]; rest = [x for x in rest if x]
        p = rest[0]; q = next(x for x in rest if bf(p, x))
        P.append(p); Qv.append(q); rest = rest[1:]
    # linear map phi: express each element of E in basis -> (x|z)
    def phi(v):
        out = 0
        for i, (p, q) in enumerate(zip(P, Qv)):
            if bf(v, q): out |= X(i + 1)
            if bf(v, p): out |= Z(i + 1)
        return out
    # check phi is an isometry onto F_2^8
    imgs = {phi(v) for v in E}; assert len(imgs) == 256
    for v in E[:40]:
        for w in E[:40]: assert BM[phi(v), phi(w)] == bf(v, w)
    S = sorted({phi(canon((1 << i) | (1 << j))) for i in range(10) for j in range(i + 1, 10)})
    assert len(S) == 45
    return S
